public class MainActivity extends Activity {
    static final String PREFS="alarm", ITEMS="alarms_json", LEGACY_ON="on";
    static final int DAILY=0, WEEKLY=1, MONTHLY=2, YEARLY=3;
    LinearLayout list;
    android.content.SharedPreferences prefs;
    final Handler previewHandler=new Handler(Looper.getMainLooper());
    MediaPlayer previewPlayer;
    Runnable previewStop;
    final int ink=0xff202820, green=0xff466b50, muted=0xff737b70, bg=0xfff5f7f2;

    @Override public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences(PREFS,MODE_PRIVATE);migrateLegacyAlarm();getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);render();requestNotificationPermission();}
    @Override protected void onResume(){super.onResume();if(prefs!=null)AlarmScheduler.scheduleAll(this);if(list!=null)render();}

    void render(){
        ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(20),dp(24),dp(20),dp(30));root.setBackgroundColor(bg);scroll.addView(root);
        TextView title=new TextView(this);title.setText("Alarm");title.setTextSize(30);title.setTextColor(ink);title.setTypeface(null,Typeface.BOLD);root.addView(title);
        TextView version=new TextView(this);version.setText("Báo thức của bạn");version.setTextSize(14);version.setTextColor(muted);LinearLayout.LayoutParams vp=params(-1,-2);vp.bottomMargin=dp(14);root.addView(version,vp);
        TextView samsungNote=new TextView(this);samsungNote.setText("Samsung: vào Thông tin ứng dụng > Pin > Không hạn chế để tránh hệ thống ngắt báo thức.");samsungNote.setTextSize(12);samsungNote.setTextColor(muted);root.addView(samsungNote,withBottom(12));
        boolean exactAllowed=AlarmScheduler.hasExactPermission(this);boolean samsung="samsung".equalsIgnoreCase(Build.MANUFACTURER);boolean notificationsAllowed=Build.VERSION.SDK_INT<33||checkSelfPermission("android.permission.POST_NOTIFICATIONS")==PackageManager.PERMISSION_GRANTED;
        if(!exactAllowed||samsung||!notificationsAllowed){
            LinearLayout warning=card();StringBuilder guidance=new StringBuilder();if(!exactAllowed)guidance.append("Chưa được cấp quyền Báo thức và lời nhắc; báo thức hiện chưa được hệ thống lên lịch. ");if(!notificationsAllowed)guidance.append("Hãy bật thông báo để thấy thông báo và nút tắt chuông. ");if(samsung)guidance.append("Trên Samsung, đặt Pin thành Không hạn chế để hệ thống không đưa app vào chế độ ngủ.");TextView text=new TextView(this);text.setText(guidance.toString());text.setTextSize(13);text.setTextColor(ink);warning.addView(text);
            if(!exactAllowed){Button grant=button("CHO PHÉP BÁO THỨC CHÍNH XÁC");grant.setOnClickListener(v->explainExactAlarmAccess());warning.addView(grant);}
            if(samsung){Button battery=button("CÀI ĐẶT PIN / CHẠY NỀN");battery.setOnClickListener(v->openAppSettings());warning.addView(battery);}
            if(!notificationsAllowed){Button notification=button("BẬT THÔNG BÁO");notification.setOnClickListener(v->openNotificationSettings());warning.addView(notification);}
            root.addView(warning,withBottom(12));
        }
        LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER_VERTICAL);TextView section=new TextView(this);section.setText("Báo thức");section.setTextSize(20);section.setTextColor(ink);section.setTypeface(null,Typeface.BOLD);actions.addView(section,new LinearLayout.LayoutParams(0,-2,1));Button add=button("+ THÊM");add.setOnClickListener(v->editAlarm(null));actions.addView(add);root.addView(actions,withBottom(10));
        Button test=button("THỬ CHUÔNG NGAY");test.setOnClickListener(v->previewAlarmSound());root.addView(test,withBottom(4));
        Button delayedTest=button("KIỂM TRA REO KHI ĐÓNG APP · 1 PHÚT");delayedTest.setOnClickListener(v->scheduleDeliveryTest());root.addView(delayedTest,withBottom(8));
        TextView scheduleStatus=new TextView(this);scheduleStatus.setText(alarmScheduleStatus());scheduleStatus.setTextSize(12);scheduleStatus.setTextColor(muted);root.addView(scheduleStatus,withBottom(14));
        list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);
        ArrayList<AlarmItem> alarms=AlarmStore.load(this);alarms.sort(Comparator.comparingInt((AlarmItem a)->a.hour).thenComparingInt(a->a.minute));
        if(alarms.isEmpty()){TextView empty=new TextView(this);empty.setText("Chưa có báo thức. Nhấn + THÊM để tạo báo thức mới.");empty.setTextSize(14);empty.setTextColor(muted);empty.setGravity(Gravity.CENTER);empty.setPadding(dp(16),dp(24),dp(16),dp(24));list.addView(empty);}
        for(AlarmItem item:alarms)addAlarmCard(item);
        setContentView(scroll);
    }
    void addAlarmCard(AlarmItem item){
        LinearLayout box=card();LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView time=new TextView(this);time.setText(String.format(Locale.getDefault(),"%02d:%02d",item.hour,item.minute));time.setTextSize(34);time.setTextColor(ink);time.setTypeface(null,Typeface.NORMAL);top.addView(time,new LinearLayout.LayoutParams(0,-2,1));Switch toggle=new Switch(this);toggle.setChecked(item.enabled);toggle.setOnCheckedChangeListener((b,checked)->{item.enabled=checked;AlarmStore.upsert(this,item);if(checked){if(AlarmScheduler.scheduleOne(this,item))Toast.makeText(this,"Đã lên lịch báo thức.",Toast.LENGTH_SHORT).show();else explainExactAlarmAccess();}else AlarmScheduler.cancel(this,item.id);render();});top.addView(toggle);box.addView(top);
        TextView label=new TextView(this);label.setText(item.label.isEmpty()?"Báo thức":item.label);label.setTextSize(16);label.setTextColor(ink);label.setTypeface(null,Typeface.BOLD);box.addView(label);
        TextView repeat=new TextView(this);repeat.setText(AlarmScheduler.repeatLabel(item));repeat.setTextSize(13);repeat.setTextColor(muted);repeat.setPadding(0,dp(3),0,dp(7));box.addView(repeat);
        LinearLayout buttons=new LinearLayout(this);Button edit=button("SỬA");edit.setOnClickListener(v->editAlarm(item));buttons.addView(edit);Button delete=button("XÓA");delete.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("Xóa báo thức này?").setNegativeButton("HỦY",null).setPositiveButton("XÓA",(d,w)->{AlarmScheduler.cancel(this,item.id);AlarmStore.remove(this,item.id);render();}).show());buttons.addView(delete);box.addView(buttons);list.addView(box,withBottom(10));
    }
    LinearLayout card(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(16),dp(13),dp(16),dp(12));box.setBackgroundColor(0xffffffff);return box;}
    Button button(String text){Button b=new Button(this);b.setText(text);b.setTextSize(12);b.setTextColor(green);b.setAllCaps(false);return b;}
    void editAlarm(AlarmItem existing){
        AlarmItem base=existing==null?new AlarmItem():existing.copy();LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(8),dp(4),dp(8),dp(4));ScrollView sc=new ScrollView(this);sc.addView(form);
        addLabel(form,"TÊN BÁO THỨC");EditText label=new EditText(this);label.setSingleLine(true);label.setHint("Ví dụ: Uống thuốc");label.setText(base.label);form.addView(label);
        addLabel(form,"NGÀY BẮT ĐẦU");DatePicker date=new DatePicker(this);date.setCalendarViewShown(false);date.setSpinnersShown(true);Calendar dateValue=base.startDate();date.updateDate(dateValue.get(Calendar.YEAR),dateValue.get(Calendar.MONTH),dateValue.get(Calendar.DAY_OF_MONTH));form.addView(date,new LinearLayout.LayoutParams(-1,-2));
        addLabel(form,"GIỜ REO");
        LinearLayout clock=new LinearLayout(this);clock.setGravity(Gravity.CENTER);clock.setPadding(dp(8),dp(10),dp(8),dp(10));clock.setBackgroundColor(0xfff1f5ef);
        NumberPicker hour=new NumberPicker(this);hour.setMinValue(0);hour.setMaxValue(23);hour.setFormatter(value->String.format(Locale.getDefault(),"%02d",value));hour.setValue(base.hour);hour.setWrapSelectorWheel(true);hour.setDescendantFocusability(NumberPicker.FOCUS_BLOCK_DESCENDANTS);
        TextView colon=new TextView(this);colon.setText(":");colon.setTextSize(34);colon.setTextColor(ink);colon.setGravity(Gravity.CENTER);colon.setPadding(dp(4),0,dp(4),0);
        NumberPicker minute=new NumberPicker(this);minute.setMinValue(0);minute.setMaxValue(59);minute.setFormatter(value->String.format(Locale.getDefault(),"%02d",value));minute.setValue(base.minute);minute.setWrapSelectorWheel(true);minute.setDescendantFocusability(NumberPicker.FOCUS_BLOCK_DESCENDANTS);
        clock.addView(hour,new LinearLayout.LayoutParams(dp(96),dp(112)));clock.addView(colon,new LinearLayout.LayoutParams(dp(28),dp(112)));clock.addView(minute,new LinearLayout.LayoutParams(dp(96),dp(112)));form.addView(clock,new LinearLayout.LayoutParams(-1,-2));
        addLabel(form,"LẶP LẠI");Spinner repeat=new Spinner(this);repeat.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Mỗi ngày","Mỗi tuần","Mỗi tháng","Mỗi năm"}));repeat.setSelection(base.repeat);form.addView(repeat);
        LinearLayout weekBox=new LinearLayout(this);weekBox.setOrientation(LinearLayout.VERTICAL);addLabel(weekBox,"LẶP VÀO THỨ");String[] days={"Thứ 2","Thứ 3","Thứ 4","Thứ 5","Thứ 6","Thứ 7","Chủ nhật"};CheckBox[] checks=new CheckBox[7];int defaultMask=1<<((dateValue.get(Calendar.DAY_OF_WEEK)+5)%7);for(int i=0;i<7;i++){checks[i]=new CheckBox(this);checks[i].setText(days[i]);checks[i].setChecked((base.weekdays==0?defaultMask:base.weekdays&(1<<i))!=0);weekBox.addView(checks[i]);}weekBox.setVisibility(base.repeat==WEEKLY?View.VISIBLE:View.GONE);form.addView(weekBox);repeat.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){weekBox.setVisibility(pos==WEEKLY?View.VISIBLE:View.GONE);}});
        addLabel(form,"SỐ LẦN REO");Spinner rings=new Spinner(this);rings.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"1 lần","2 lần","3 lần"}));rings.setSelection(Math.max(0,Math.min(2,base.rings-1)));form.addView(rings);
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle(existing==null?"Thêm báo thức":"Sửa báo thức").setView(sc).setNegativeButton("HỦY",null).setPositiveButton("LƯU",null).create();dialog.setOnShowListener(d->{dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{int mask=0;for(int i=0;i<7;i++)if(checks[i].isChecked())mask|=1<<i;if(repeat.getSelectedItemPosition()==WEEKLY&&mask==0){Toast.makeText(this,"Chọn ít nhất một thứ",Toast.LENGTH_SHORT).show();return;}base.label=label.getText().toString().trim();if(base.label.isEmpty())base.label="Báo thức";base.hour=hour.getValue();base.minute=minute.getValue();base.repeat=repeat.getSelectedItemPosition();base.weekdays=mask;base.rings=rings.getSelectedItemPosition()+1;base.startYear=date.getYear();base.startMonth=date.getMonth();base.startDay=date.getDayOfMonth();if(existing==null){base.id=AlarmStore.nextId(this);base.enabled=true;}AlarmStore.upsert(this,base);boolean scheduled=!base.enabled||AlarmScheduler.scheduleOne(this,base);dialog.dismiss();render();if(!scheduled)explainExactAlarmAccess();else if(base.enabled)Toast.makeText(this,"Đã lên lịch báo thức.",Toast.LENGTH_SHORT).show();});});dialog.show();
    }
    void addLabel(LinearLayout root,String text){TextView t=new TextView(this);t.setText(text);t.setTextSize(12);t.setTextColor(muted);t.setPadding(dp(4),dp(12),0,dp(3));root.addView(t);}
    void migrateLegacyAlarm(){if(prefs.contains(ITEMS))return;if(!prefs.getBoolean(LEGACY_ON,false))return;AlarmItem item=new AlarmItem();item.id=1;item.label="Báo thức";item.enabled=true;item.hour=prefs.getInt("hour",7);item.minute=prefs.getInt("minute",0);item.rings=prefs.getInt("rings",1);item.repeat=prefs.getInt("repeat",DAILY);item.weekdays=prefs.getInt("weekdays",0);Calendar now=Calendar.getInstance();item.startYear=prefs.getInt("startYear",now.get(Calendar.YEAR));item.startMonth=prefs.getInt("startMonth",now.get(Calendar.MONTH));item.startDay=prefs.getInt("startDay",now.get(Calendar.DAY_OF_MONTH));AlarmStore.upsert(this,item);}
    void requestNotificationPermission(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},10);return;}maybeExplainAlarmSetup();}
    @Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] grantResults){super.onRequestPermissionsResult(requestCode,permissions,grantResults);if(requestCode==10)maybeExplainAlarmSetup();}
    void maybeExplainAlarmSetup(){if(isFinishing())return;boolean exactMissing=!AlarmScheduler.hasExactPermission(this);boolean samsung="samsung".equalsIgnoreCase(Build.MANUFACTURER);boolean batteryPrompt=samsung&&!prefs.getBoolean("samsung_battery_prompted",false);boolean exactPrompt=exactMissing&&!prefs.getBoolean("exact_alarm_prompted",false);if(!exactPrompt&&!batteryPrompt)return;if(exactPrompt)prefs.edit().putBoolean("exact_alarm_prompted",true).apply();if(batteryPrompt)prefs.edit().putBoolean("samsung_battery_prompted",true).apply();String message;if(exactMissing&&samsung)message="Để báo đúng giờ khi app đóng, hãy bật quyền Báo thức và lời nhắc. Trên Samsung, hãy đặt Pin của Alarm thành Không hạn chế để hệ thống không ngủ app.";else if(exactMissing)message="Android cần quyền đặc biệt Báo thức và lời nhắc để chuông reo đúng giờ khi app đóng.";else message="Để Samsung không đưa Alarm vào chế độ ngủ, hãy mở cài đặt Pin và chọn Không hạn chế cho ứng dụng.";AlertDialog.Builder dialog=new AlertDialog.Builder(this).setTitle(exactMissing?"Thiết lập quyền báo thức":"Cho phép chạy nền trên Samsung").setMessage(message).setNegativeButton("ĐỂ SAU",null);if(exactMissing)dialog.setPositiveButton("BÁO THỨC & LỜI NHẮC",(d,w)->requestExactAlarmAccess());if(samsung)dialog.setNeutralButton("CÀI ĐẶT PIN",(d,w)->openAppSettings());else if(!exactMissing)dialog.setPositiveButton("MỞ CÀI ĐẶT",(d,w)->openAppSettings());dialog.show();}
    void explainExactAlarmAccess(){new AlertDialog.Builder(this).setTitle("Cho phép báo thức đúng giờ").setMessage("Android cần quyền đặc biệt “Báo thức và lời nhắc” để lên lịch chuông khi app đóng hoặc điện thoại đang khóa. Mình sẽ mở trang cài đặt của Alarm để bạn bật quyền này.").setNegativeButton("ĐỂ SAU",null).setPositiveButton("MỞ CÀI ĐẶT",(d,w)->requestExactAlarmAccess()).show();}
    void openAppSettings(){try{startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));}catch(Exception ignored){}}
    void openNotificationSettings(){try{Intent i=new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName());startActivity(i);}catch(Exception e){openAppSettings();}}
    void previewAlarmSound(){stopPreview();MediaPlayer player=null;try{Uri uri=RingtoneManager.getActualDefaultRingtoneUri(this,RingtoneManager.TYPE_ALARM);if(uri==null)uri=RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM);if(uri==null){Toast.makeText(this,"Điện thoại chưa chọn âm báo thức mặc định.",Toast.LENGTH_LONG).show();return;}player=new MediaPlayer();previewPlayer=player;player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());player.setDataSource(this,uri);AlarmAudio.preferConnectedHeadset(this,player);MediaPlayer active=player;player.setOnCompletionListener(done->stopPreview(active));player.setOnErrorListener((failed,w,e)->{stopPreview(active);return true;});player.prepare();player.start();previewStop=()->stopPreview(active);previewHandler.postDelayed(previewStop,15000);}catch(Exception e){if(player!=null){try{player.release();}catch(Exception ignored){}}previewPlayer=null;android.util.Log.e("AlarmPlayback","Unable to preview alarm sound",e);Toast.makeText(this,"Không mở được âm báo thức.",Toast.LENGTH_LONG).show();}}
    String alarmScheduleStatus(){AlarmManager manager=(AlarmManager)getSystemService(ALARM_SERVICE);AlarmManager.AlarmClockInfo next=manager.getNextAlarmClock();if(next==null||next.getShowIntent()==null||!getPackageName().equals(next.getShowIntent().getCreatorPackage()))return "Android chưa xác nhận báo thức kế tiếp của Alarm. Hãy bật báo thức và kiểm tra quyền Báo thức & lời nhắc.";return "Android đã nhận báo thức kế tiếp: "+new java.text.SimpleDateFormat("EEE, HH:mm",Locale.getDefault()).format(new Date(next.getTriggerTime()));}
    void scheduleDeliveryTest(){if(!AlarmScheduler.hasExactPermission(this)){explainExactAlarmAccess();return;}try{long at=System.currentTimeMillis()+60_000L;Intent intent=new Intent(this,AlarmReceiver.class).putExtra("alarm_test",true);PendingIntent operation=PendingIntent.getBroadcast(this,999999,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent show=PendingIntent.getActivity(this,999999,new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((AlarmManager)getSystemService(ALARM_SERVICE)).setAlarmClock(new AlarmManager.AlarmClockInfo(at,show),operation);Toast.makeText(this,"Đã hẹn thử reo sau 1 phút. Giờ bạn có thể đóng app.",Toast.LENGTH_LONG).show();}catch(RuntimeException e){android.util.Log.e("AlarmScheduler","Could not schedule delivery test",e);Toast.makeText(this,"Không hẹn được chuông thử. Kiểm tra quyền Báo thức & lời nhắc.",Toast.LENGTH_LONG).show();}}
    void stopPreview(){if(previewStop!=null){previewHandler.removeCallbacks(previewStop);previewStop=null;}if(previewPlayer!=null){try{if(previewPlayer.isPlaying())previewPlayer.stop();}catch(RuntimeException ignored){}try{previewPlayer.release();}catch(RuntimeException ignored){}previewPlayer=null;}}
    void stopPreview(MediaPlayer target){if(previewPlayer==target)stopPreview();}
    @Override protected void onDestroy(){stopPreview();super.onDestroy();}
    void requestExactAlarmAccess(){if(Build.VERSION.SDK_INT<31)return;try{if(Build.VERSION.SDK_INT>=33){openAppSettings();return;}Intent i=new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName()));startActivity(i);}catch(Exception e){openAppSettings();}}
    LinearLayout.LayoutParams params(int w,int h){return new LinearLayout.LayoutParams(w,h);}LinearLayout.LayoutParams withBottom(int bottom){LinearLayout.LayoutParams p=params(-1,-2);p.bottomMargin=dp(bottom);return p;}int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
}

class AlarmItem {
    int id,hour=7,minute=0,rings=1,repeat=MainActivity.DAILY,weekdays=0,startYear,startMonth,startDay;String label="";boolean enabled=true;
    Calendar startDate(){Calendar c=Calendar.getInstance();if(startYear==0){startYear=c.get(Calendar.YEAR);startMonth=c.get(Calendar.MONTH);startDay=c.get(Calendar.DAY_OF_MONTH);}c.set(startYear,startMonth,startDay,0,0,0);c.set(Calendar.MILLISECOND,0);return c;}
    AlarmItem copy(){AlarmItem a=new AlarmItem();a.id=id;a.hour=hour;a.minute=minute;a.rings=rings;a.repeat=repeat;a.weekdays=weekdays;a.startYear=startYear;a.startMonth=startMonth;a.startDay=startDay;a.label=label;a.enabled=enabled;return a;}
    JSONObject json(){JSONObject o=new JSONObject();try{o.put("id",id);o.put("hour",hour);o.put("minute",minute);o.put("rings",rings);o.put("repeat",repeat);o.put("weekdays",weekdays);o.put("startYear",startYear);o.put("startMonth",startMonth);o.put("startDay",startDay);o.put("label",label);o.put("enabled",enabled);}catch(Exception ignored){}return o;}
    static AlarmItem from(JSONObject o){AlarmItem a=new AlarmItem();a.id=o.optInt("id",1);a.hour=o.optInt("hour",7);a.minute=o.optInt("minute",0);a.rings=o.optInt("rings",1);a.repeat=o.optInt("repeat",0);a.weekdays=o.optInt("weekdays",0);a.startYear=o.optInt("startYear",0);a.startMonth=o.optInt("startMonth",0);a.startDay=o.optInt("startDay",1);a.label=o.optString("label","");a.enabled=o.optBoolean("enabled",true);return a;}
}

class AlarmStore {
    static ArrayList<AlarmItem> load(Context c){ArrayList<AlarmItem> out=new ArrayList<>();String raw=c.getSharedPreferences(MainActivity.PREFS,0).getString(MainActivity.ITEMS,"[]");try{JSONArray arr=new JSONArray(raw);for(int i=0;i<arr.length();i++)out.add(AlarmItem.from(arr.getJSONObject(i)));}catch(Exception ignored){}return out;}
    static void save(Context c,ArrayList<AlarmItem> items){JSONArray arr=new JSONArray();for(AlarmItem a:items)arr.put(a.json());c.getSharedPreferences(MainActivity.PREFS,0).edit().putString(MainActivity.ITEMS,arr.toString()).apply();}
    static void upsert(Context c,AlarmItem item){ArrayList<AlarmItem> items=load(c);boolean found=false;for(int i=0;i<items.size();i++)if(items.get(i).id==item.id){items.set(i,item.copy());found=true;break;}if(!found)items.add(item.copy());save(c,items);}
    static void remove(Context c,int id){ArrayList<AlarmItem> items=load(c);for(Iterator<AlarmItem> it=items.iterator();it.hasNext();)if(it.next().id==id)it.remove();save(c,items);}
    static AlarmItem get(Context c,int id){for(AlarmItem a:load(c))if(a.id==id)return a;return null;}
    static int nextId(Context c){android.content.SharedPreferences p=c.getSharedPreferences(MainActivity.PREFS,0);int next=p.getInt("next_id",2);p.edit().putInt("next_id",next+1).apply();return next;}
}

class AlarmScheduler {
    static boolean hasExactPermission(Context c){if(Build.VERSION.SDK_INT<31)return true;if(Build.VERSION.SDK_INT>=33)return c.checkSelfPermission("android.permission.USE_EXACT_ALARM")==PackageManager.PERMISSION_GRANTED;return((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).canScheduleExactAlarms();}
    static PendingIntent pending(Context c,AlarmItem item){Intent i=new Intent(c,AlarmReceiver.class).putExtra("alarm_id",item.id);return PendingIntent.getBroadcast(c,item.id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    static PendingIntent showPending(Context c,AlarmItem item){Intent i=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);return PendingIntent.getActivity(c,100000+item.id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    static boolean scheduleOne(Context c,AlarmItem item){if(!item.enabled){cancel(c,item.id);return true;}if(!hasExactPermission(c)){android.util.Log.w("AlarmScheduler","Exact alarm access is not granted");return false;}long at=nextTime(item,System.currentTimeMillis());AlarmManager manager=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);PendingIntent op=pending(c,item);try{if(Build.VERSION.SDK_INT>=23)manager.setAlarmClock(new AlarmManager.AlarmClockInfo(at,showPending(c,item)),op);else manager.setExact(AlarmManager.RTC_WAKEUP,at,op);android.util.Log.i("AlarmScheduler","Scheduled alarm "+item.id+" at "+new Date(at));return true;}catch(RuntimeException e){android.util.Log.e("AlarmScheduler","Could not schedule alarm "+item.id,e);return false;}}
    static void scheduleAll(Context c){if(!hasExactPermission(c))return;for(AlarmItem item:AlarmStore.load(c))if(item.enabled)scheduleOne(c,item);}
    static void cancel(Context c,int id){Intent i=new Intent(c,AlarmReceiver.class);PendingIntent pi=PendingIntent.getBroadcast(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).cancel(pi);pi.cancel();}
    static long nextTime(AlarmItem item,long now){Calendar start=item.startDate(),candidate=(Calendar)start.clone();candidate.set(Calendar.HOUR_OF_DAY,item.hour);candidate.set(Calendar.MINUTE,item.minute);candidate.set(Calendar.SECOND,0);candidate.set(Calendar.MILLISECOND,0);if(item.repeat==MainActivity.DAILY){while(candidate.getTimeInMillis()<=now)candidate.add(Calendar.DAY_OF_YEAR,1);return candidate.getTimeInMillis();}if(item.repeat==MainActivity.WEEKLY){for(int i=0;i<370;i++){int dow=(candidate.get(Calendar.DAY_OF_WEEK)+5)%7;if((item.weekdays&(1<<dow))!=0&&candidate.getTimeInMillis()>now)return candidate.getTimeInMillis();candidate.add(Calendar.DAY_OF_YEAR,1);}return candidate.getTimeInMillis();}int day=start.get(Calendar.DAY_OF_MONTH);if(item.repeat==MainActivity.MONTHLY){candidate.set(Calendar.DAY_OF_MONTH,1);for(int i=0;i<240;i++){candidate.set(Calendar.DAY_OF_MONTH,Math.min(day,candidate.getActualMaximum(Calendar.DAY_OF_MONTH)));if(candidate.getTimeInMillis()>now)return candidate.getTimeInMillis();candidate.set(Calendar.DAY_OF_MONTH,1);candidate.add(Calendar.MONTH,1);}return candidate.getTimeInMillis();}int month=start.get(Calendar.MONTH);for(int i=0;i<100;i++){candidate.set(Calendar.YEAR,start.get(Calendar.YEAR)+i);candidate.set(Calendar.MONTH,month);candidate.set(Calendar.DAY_OF_MONTH,1);candidate.set(Calendar.DAY_OF_MONTH,Math.min(day,candidate.getActualMaximum(Calendar.DAY_OF_MONTH)));if(candidate.getTimeInMillis()>now)return candidate.getTimeInMillis();}return candidate.getTimeInMillis();}
    static String repeatLabel(AlarmItem a){String[] names={"Mỗi ngày","Mỗi tuần","Mỗi tháng","Mỗi năm"};if(a.repeat!=MainActivity.WEEKLY)return names[Math.max(0,Math.min(3,a.repeat))];String[] days={"T2","T3","T4","T5","T6","T7","CN"};StringBuilder b=new StringBuilder();for(int i=0;i<7;i++)if((a.weekdays&(1<<i))!=0){if(b.length()>0)b.append(", ");b.append(days[i]);}return names[1]+" · "+b;}
}

class AlarmAudio {
    static void preferConnectedHeadset(Context context,MediaPlayer player){if(Build.VERSION.SDK_INT<28)return;try{AudioManager manager=(AudioManager)context.getSystemService(Context.AUDIO_SERVICE);if(manager==null)return;AudioDeviceInfo[] outputs=manager.getDevices(AudioManager.GET_DEVICES_OUTPUTS);int[] priority={AudioDeviceInfo.TYPE_BLUETOOTH_A2DP,AudioDeviceInfo.TYPE_BLE_HEADSET,AudioDeviceInfo.TYPE_WIRED_HEADSET,AudioDeviceInfo.TYPE_WIRED_HEADPHONES,AudioDeviceInfo.TYPE_USB_HEADSET,AudioDeviceInfo.TYPE_HEARING_AID,AudioDeviceInfo.TYPE_BLUETOOTH_SCO};for(int type:priority){if(type==AudioDeviceInfo.TYPE_BLE_HEADSET&&Build.VERSION.SDK_INT<31)continue;if(type==AudioDeviceInfo.TYPE_USB_HEADSET&&Build.VERSION.SDK_INT<26)continue;if(type==AudioDeviceInfo.TYPE_HEARING_AID&&Build.VERSION.SDK_INT<28)continue;for(AudioDeviceInfo output:outputs)if(output.getType()==type){boolean selected=player.setPreferredDevice(output);android.util.Log.i("AlarmPlayback",selected?"Routing alarm to connected headset":"Could not select connected headset route");return;}}}catch(RuntimeException e){android.util.Log.w("AlarmPlayback","Unable to select connected headset route",e);}}
}

class AlarmReceiver extends BroadcastReceiver {@Override public void onReceive(Context c,Intent i){android.util.Log.i("AlarmReceiver","Alarm broadcast received; test="+i.getBooleanExtra("alarm_test",false));if(i.getBooleanExtra("alarm_test",false)){AlarmPlaybackService.start(c,-2,"Kiểm tra báo thức",1);return;}int id=i.getIntExtra("alarm_id",-1);AlarmItem item=AlarmStore.get(c,id);if(item==null||!item.enabled){android.util.Log.w("AlarmReceiver","Alarm item missing or disabled: "+id);return;}AlarmScheduler.scheduleOne(c,item);AlarmPlaybackService.start(c,item.id,item.label,item.rings);}}
class BootReceiver extends BroadcastReceiver {@Override public void onReceive(Context c,Intent i){AlarmScheduler.scheduleAll(c);}}
class StopReceiver extends BroadcastReceiver {@Override public void onReceive(Context c,Intent i){c.stopService(new Intent(c,AlarmPlaybackService.class));}}

class AlarmPlaybackService extends Service {
    static final int NOTIFICATION_ID=700;final Handler handler=new Handler(Looper.getMainLooper());final HashMap<Integer,Playback> active=new HashMap<>();PowerManager.WakeLock wakeLock;boolean foreground=false;
    static boolean start(Context c,int id,String label,int rings){try{Intent i=new Intent(c,AlarmPlaybackService.class).putExtra("alarm_id",id).putExtra("alarm_label",label).putExtra("rings",rings);if(Build.VERSION.SDK_INT>=26)c.startForegroundService(i);else c.startService(i);return true;}catch(RuntimeException e){android.util.Log.e("AlarmPlayback","Unable to start playback service",e);return false;}}
    @Override public int onStartCommand(Intent intent,int flags,int startId){try{int id=intent==null?-1:intent.getIntExtra("alarm_id",-1);String label=intent==null?"Báo thức":intent.getStringExtra("alarm_label");int rings=intent==null?1:intent.getIntExtra("rings",1);if(active.containsKey(id))finish(active.get(id));Playback p=new Playback(id,label==null||label.isEmpty()?"Báo thức":label,Math.max(1,Math.min(3,rings)));active.put(id,p);if(wakeLock==null){PowerManager pm=(PowerManager)getSystemService(POWER_SERVICE);wakeLock=pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,getPackageName()+":AlarmPlayback");wakeLock.setReferenceCounted(false);}if(!wakeLock.isHeld())wakeLock.acquire(10*60*1000L);showNotification(p);play(p);return START_NOT_STICKY;}catch(RuntimeException e){android.util.Log.e("AlarmPlayback","Playback service failed",e);stopSelf(startId);return START_NOT_STICKY;}}
    void showNotification(Playback p){if(Build.VERSION.SDK_INT>=26)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("alarm","Alarm",NotificationManager.IMPORTANCE_HIGH));Intent stop=new Intent(this,StopReceiver.class);PendingIntent stopPi=PendingIntent.getBroadcast(this,700,stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"alarm"):new Notification.Builder(this);Icon stopIcon=Icon.createWithResource(this,android.R.drawable.ic_media_pause);Notification n=b.setSmallIcon(R.drawable.ic_alarm_notification).setContentTitle(p.label).setContentText("Đang reo · "+p.total+" lần").setCategory(Notification.CATEGORY_ALARM).setOngoing(true).addAction(new Notification.Action.Builder(stopIcon,"TẮT",stopPi).build()).build();if(!foreground){startForeground(NOTIFICATION_ID,n);foreground=true;}else((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(NOTIFICATION_ID,n);}
    void play(Playback p){if(!active.containsKey(p.id))return;try{android.net.Uri uri=RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM);if(uri==null)uri=RingtoneManager.getDefaultUri(RingtoneManager.TYPE_RINGTONE);if(uri==null){finish(p);return;}MediaPlayer mp=new MediaPlayer();p.player=mp;mp.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());mp.setDataSource(this,uri);AlarmAudio.preferConnectedHeadset(this,mp);mp.setOnCompletionListener(done->{done.release();p.player=null;p.played++;if(p.played<p.total){p.next=()->play(p);handler.postDelayed(p.next,1200);}else finish(p);});mp.setOnErrorListener((bad,w,e)->{finish(p);return true;});mp.prepare();mp.start();}catch(Exception e){finish(p);}}
    void finish(Playback p){if(p.next!=null)handler.removeCallbacks(p.next);if(p.player!=null){try{if(p.player.isPlaying())p.player.stop();}catch(Exception ignored){}try{p.player.release();}catch(Exception ignored){}p.player=null;}active.remove(p.id);if(active.isEmpty()){if(wakeLock!=null&&wakeLock.isHeld())wakeLock.release();if(foreground){if(Build.VERSION.SDK_INT>=24)stopForeground(STOP_FOREGROUND_REMOVE);else stopForeground(true);foreground=false;}stopSelf();}}
    @Override public void onDestroy(){handler.removeCallbacksAndMessages(null);for(Playback p:new ArrayList<>(active.values())){if(p.player!=null){try{p.player.release();}catch(Exception ignored){}}}active.clear();if(wakeLock!=null&&wakeLock.isHeld())wakeLock.release();((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(NOTIFICATION_ID);super.onDestroy();}
    @Override public IBinder onBind(Intent i){return null;}
    static class Playback{final int id,total;final String label;int played;MediaPlayer player;Runnable next;Playback(int i,String l,int n){id=i;label=l;total=n;}}
}
